// Prototype (Declaration)
int validate_input(int value);

// Function Definition (Decomposition Step 1)
int validate_input(int value) {
    if (value < 0) return 0;
    return 1;
}

// Function Definition (Higher level task)
long process_data(int input) {
    if (validate_input(input)) {
        return (long)input * 100;
    }
    return 0L;
}

// Function Call / Usage
int user_data = 50;
long final_result = process_data(user_data);
